{# =======================================================
  ✅ SAFE CONTEXT SETUP (No runtime errors)
======================================================= #}
{%- set driver_doc = frappe.db.exists('Driver', doc.driver) and frappe.get_doc('Driver', doc.driver) or None -%}
{%- set staff_doc = driver_doc and driver_doc.staff and frappe.db.exists('Staff', driver_doc.staff) and frappe.get_doc('Staff', driver_doc.staff) or None -%}
{%- set company_name = staff_doc and staff_doc.company_name or doc.company -%}
{%- set company = frappe.db.exists('Company', company_name) and frappe.get_doc('Company', company_name) or None -%}

{# --- Child Documents --- #}
{%- set company_docs = company and frappe.get_all('Documents', filters={'parent': company.name}, fields=['document_type','document_no','expiry_date']) or [] -%}
{%- set driver_docs = driver_doc and frappe.get_all('Documents', filters={'parent': driver_doc.name}, fields=['document_type','document_no','expiry_date']) or [] -%}
{%- set staff_docs = staff_doc and frappe.get_all('Documents', filters={'parent': staff_doc.name}, fields=['document_type','document_no','expiry_date']) or [] -%}
{%- set vehicle_docs = frappe.get_all('Documents', filters={'parent': doc.assigned_vehicle}, fields=['document_type','document_no','expiry_date']) or [] -%}

{# --- Helper Macro: Expiry Color --- #}
{% macro expiry_color(expiry_date) -%}
  {% if not expiry_date %}
    <span style="color:#888;">N/A</span>
  {% else %}
    {% set days_left = (frappe.utils.getdate(expiry_date) - frappe.utils.getdate(frappe.utils.today())).days %}
    {% if days_left <= 0 %}
      <span style="color:red;font-weight:600;">Expired</span>
    {% elif days_left <= 30 %}
      <span style="color:orange;font-weight:600;">{{ days_left }} days left</span>
    {% elif days_left <= 60 %}
      <span style="color:goldenrod;font-weight:600;">{{ days_left }} days left</span>
    {% else %}
      <span style="color:green;">Valid ({{ days_left }} days)</span>
    {% endif %}
  {% endif %}
{%- endmacro %}

{# =======================================================
  🎨 STYLING
======================================================= #}
<style>
@import url('https://fonts.googleapis.com/css2?family=Ubuntu:wght@300;400;700&family=Noto+Naskh+Arabic:wght@400;700&display=swap');
body {font-family:'Ubuntu',sans-serif;font-size:14px;}
.page {page-break-after:always;}
.header-section{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #ccc;padding-bottom:5px;}
.logo img{width:110px;}
.company-names{text-align:right;}
.company-names .en{font-size:16px;font-weight:bold;}
.company-names .ar{font-family:'Noto Naskh Arabic',serif;font-size:22px;direction:rtl;}
table{width:100%;border-collapse:collapse;margin-top:10px;}
th,td{border:1px solid #aaa;padding:6px;text-align:left;}
th{background:#efdfdf;color:#07417b;font-weight:800;}
.footer-section{border-top:1px solid #ccc;margin-top:20px;font-size:12px;padding-top:5px;color:#333;}
.page-tc-content{font-family:'Noto Naskh Arabic',serif;direction:rtl;font-size:13px;line-height:1.8;text-align:right;}
</style>

{# =======================================================
  PAGE 1 - TRIP SUMMARY
======================================================= #}
<div class="page">
  <div class="header-section">
    <div class="logo">
      {% if company and company.logo %}
        <img src="{{ company.logo }}">
      {% endif %}
    </div>
    <div class="company-names">
      <div class="en">{{ company.name if company else '' }}</div>
      <div class="ar">{{ company.company_name_arabic if company else '' }}</div>
    </div>
  </div>

  <table>
    <tbody>
      <tr>
        <th>Driver</th><td>{{ driver_doc.full_name if driver_doc else doc.driver }}</td>
        <th>Iqama</th>
        <td>
          {% set iqama = driver_docs | selectattr('document_type','equalto','Iqama') | list | first %}
          {{ iqama.document_no if iqama else '-' }} - {{ expiry_color(iqama.expiry_date if iqama else None) }}
        </td>
      </tr>
      <tr>
        <th>License</th>
        <td>
          {% set lic = driver_docs | selectattr('document_type','equalto','Driving License') | list | first %}
          {{ lic.document_no if lic else '-' }} - {{ expiry_color(lic.expiry_date if lic else None) }}
        </td>
        <th>Passport</th>
        <td>
          {% set pass = staff_docs | selectattr('document_type','equalto','Passport') | list | first %}
          {{ pass.document_no if pass else '-' }} - {{ expiry_color(pass.expiry_date if pass else None) }}
        </td>
      </tr>
      <tr>
        <th>Vehicle</th><td>{{ driver_doc.vehicle_type if driver_doc else '' }} ({{ doc.assigned_vehicle or '' }})</td>
        <th>Istimara</th>
        <td>
          {% set isti = vehicle_docs | selectattr('document_type','equalto','Istimara') | list | first %}
          {{ isti.document_no if isti else '-' }} - {{ expiry_color(isti.expiry_date if isti else None) }}
        </td>
      </tr>
      <tr>
        <th>Insurance</th>
        <td>
          {% set ins = vehicle_docs | selectattr('document_type','equalto','Insurance') | list | first %}
          {{ ins.document_no if ins else '-' }} - {{ expiry_color(ins.expiry_date if ins else None) }}
        </td>
        <th>Date</th><td>{{ frappe.utils.formatdate(doc.date, 'dd-MM-yyyy') }}</td>
      </tr>
      <tr>
        <th>From</th><td>{{ doc.from_location }}</td>
        <th>To</th><td>{{ doc.to_location }}</td>
      </tr>
      <tr>
        <th>Departure</th><td>{{ doc.departure }}</td>
        <th>Arrival</th><td>{{ doc.arrival }}</td>
      </tr>
      <tr>
        <th>Distance</th><td>{{ doc.distance }} km</td>
        <th>Co-Driver</th><td>{{ doc.co_driver or '-' }}</td>
      </tr>
    </tbody>
  </table>

  <h4>Passengers</h4>
  <table>
    <thead><tr><th>#</th><th>Name</th><th>ID/Passport</th><th>Nationality</th><th>Contact</th></tr></thead>
    <tbody>
      {% for row in doc.passengers %}
      <tr>
        <td>{{ loop.index }}</td>
        <td>{{ row.passenger_name }}</td>
        <td>{{ row.idpassport_no or '' }}</td>
        <td>{{ row.nationality or '' }}</td>
        <td>{{ row.contact_no or '' }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  {% if doc.qr_code %}
  <div style="text-align:center;margin-top:15px;">
    <img src="{{ doc.qr_code }}" width="120"><br>
    <small>Scan for Trip Details</small>
  </div>
  {% endif %}

  <div class="footer-section">
    {% set cr = company_docs | selectattr('document_type','equalto','CR No') | list | first %}
    {% set reg = company_docs | selectattr('document_type','equalto','Registration No') | list | first %}
    CR: {{ cr.document_no if cr else '-' }} | Reg: {{ reg.document_no if reg else '-' }} | Phone: {{ company.phone if company else '' }}
  </div>
</div>

{# =======================================================
  PAGE 2 - ARABIC CONTRACT
======================================================= #}
<div class="page">
  <div class="header-section">
    <div class="logo">
      {% if company and company.logo %}
        <img src="{{ company.logo }}">
      {% endif %}
    </div>
    <div class="company-names">
      <div class="en">{{ company.name if company else '' }}</div>
      <div class="ar">{{ company.company_name_arabic if company else '' }}</div>
    </div>
  </div>

  <div class="page-tc-content">
    <p><strong>التاريخ الهجري:</strong> {{ doc.hijri_date or "_____" }} هـ</p>
    <p><strong>الميلادي:</strong> {{ frappe.utils.formatdate(doc.date, "dd-MM-yyyy") }} م</p>

    <h3 style="text-align:center;">عقد نقل ركاب بالحافلات</h3>
    <p>تم إبرام هذا العقد بين:</p>
    <p><strong>الطرف الأول :</strong> {{ company.company_name_arabic if company else '________' }}</p>
    <p><strong>الطرف الثاني :</strong>
      {% if doc.passengers and doc.passengers[0] %}
        {{ doc.passengers[0].passenger_name }}
      {% else %}
        ____________
      {% endif %}
    </p>

    <h3>بناءً على:</h3>
    <p>المادة (39) من اللائحة المنظمة لنشاط النقل البري للركاب وتوجيه الحافلات.</p>
    <h3>اتفق الطرفان على ما يلي:</h3>
    <p><strong>موضوع العقد :</strong><br>
      يتعهد الطرف الأول بتنفيذ عملية نقل للطرف الثاني من {{ doc.from_location or "_____" }} إلى {{ doc.to_location or "_____" }}.
    </p>

    <h3>سياسة الإلغاء والاستبدال:</h3>
    <p>يمكن إلغاء الحجز قبل موعد الرحلة بـ 24 ساعة واسترداد المبلغ بالكامل، وبعدها لا يحق الاسترداد.</p>
  </div>

  <div class="footer-section">
    CR: {{ cr.document_no if cr else '-' }} | Reg: {{ reg.document_no if reg else '-' }} | Phone: {{ company.phone if company else '' }}
  </div>
</div>

